class WeatherSystem:
    CELSIUS = 'celsius'
    FAHRENHEIT = 'fahrenheit'

    def __init__(self, city) -> None:
        self._temperature = None
        self._weather = None
        self._city = city
        self._weather_list = {}

    @property
    def temperature(self):
        return self._temperature

    @temperature.setter
    def temperature(self, value):
        self._temperature = value

    @property
    def weather(self):
        return self._weather

    @weather.setter
    def weather(self, value):
        self._weather = value

    @property
    def city(self):
        return self._city

    @city.setter
    def city(self, value):
        self._city = value

    @property
    def weather_list(self):
        return self._weather_list

    @weather_list.setter
    def weather_list(self, value):
        self._weather_list = value

    def query(self, weather_list, tmp_units=CELSIUS):
        self.weather_list = weather_list
        if self.city not in weather_list:
            return False
        else:
            self.temperature = self.weather_list[self.city]['temperature']
            self.weather = self.weather_list[self.city]['weather']

        if self.weather_list[self.city]['temperature units'] != tmp_units:
            if tmp_units == CELSIUS:
                return self._fahrenheit_to_celsius(self.temperature), self.weather
            elif tmp_units == FAHRENHEIT:
                return self._celsius_to_fahrenheit(self.temperature), self.weather
        else:
            return self.temperature, self.weather

    def set_city(self, city):
        self.city = city

    def _celsius_to_fahrenheit(self, temperature):
        return (temperature * 9 / 5) + 32

    def _fahrenheit_to_celsius(self, temperature):
        return (temperature - 32) * 5 / 9
